 public async ValueTask<KpiDefinitionVersionDto>CreateKpiDraftAsync(CompanyId c,string code,string name,KpiDataType type,string unit,KpiDirection direction,EffectivePeriod period,KpiDefinitionId? definitionId=null,decimal? minValue=null,decimal? targetValue=null,decimal? maxValue=null,CancellationToken cancellationToken=default)
 {Scope(c);if(string.IsNullOrWhiteSpace(code)||string.IsNullOrWhiteSpace(name)||string.IsNullOrWhiteSpace(unit)||period.EffectiveTo is not null&&period.EffectiveFrom>=period.EffectiveTo||minValue>maxValue)Fail(DiagnosticCodes.PerformanceInvalidResultRange);lock(sync){var normalized=code.Trim();var def=definitionId??KpiDefinitionId.From(Guid.NewGuid());if(definitionId is null&&definitions.Any(x=>x.CompanyId==c&&Eq(x.Content.Code,normalized)))Fail(DiagnosticCodes.PerformanceDuplicateKpiCode);var existing=definitions.Where(x=>x.DefinitionId==def).ToArray();if(existing.Any(x=>x.CompanyId!=c))Fail(DiagnosticCodes.PerformanceCrossCompanyReference);var dto=new KpiDefinitionVersionDto(KpiDefinitionVersionId.From(Guid.NewGuid()),def,c,existing.Length+1,period,KpiLifecycleStatus.DRAFT,new(normalized,name.Trim(),null,type,unit.Trim(),direction,minValue,targetValue,maxValue));definitions.Add(dto);Audit(c,"PERFORMANCE.KPI_DEFINITION_CREATED","KpiDefinitionVersion",dto.Id.Value,cancellationToken).GetAwaiter().GetResult();return dto;}}
 public async ValueTask<KpiDefinitionVersionDto>PublishKpiAsync(CompanyId c,KpiDefinitionVersionId id,CancellationToken cancellationToken=default){Scope(c);lock(sync){var d=Definition(c,id);if(d.LifecycleStatus!=KpiLifecycleStatus.DRAFT)Fail(DiagnosticCodes.PerformancePublishedPolicyImmutable);if(definitions.Any(x=>x.Id!=id&&x.DefinitionId==d.DefinitionId&&x.LifecycleStatus==KpiLifecycleStatus.PUBLISHED&&x.EffectivePeriod.Overlaps(d.EffectivePeriod)))Fail(DiagnosticCodes.PerformanceKpiAssignmentAmbiguous);var published=d with{LifecycleStatus=KpiLifecycleStatus.PUBLISHED};definitions[definitions.IndexOf(d)]=published;Audit(c,"PERFORMANCE.KPI_DEFINITION_PUBLISHED","KpiDefinitionVersion",id.Value,cancellationToken).GetAwaiter().GetResult();return published;}}
 public KpiDefinitionVersionDto ResolveKpi(CompanyId c,string code,DateOnly date){Scope(c);var found=definitions.Where(x=>x.CompanyId==c&&Eq(x.Content.Code,code)&&x.LifecycleStatus==KpiLifecycleStatus.PUBLISHED&&x.EffectivePeriod.Contains(date)).ToArray();if(found.Length==0)Fail(DiagnosticCodes.PerformanceKpiDefinitionNotFound);if(found.Length>1)Fail(DiagnosticCodes.PerformanceKpiAssignmentAmbiguous);return found[0];}
 public async ValueTask<KpiAssignmentDto>AssignAsync(CompanyId c,KpiDefinitionVersionId id,KpiScope scope,decimal weight,EffectivePeriod period,PayCalc24.Contracts.FormulaRepository.FormulaVersionId? scoringFormulaVersionId=null,CancellationToken cancellationToken=default)
 {Scope(c);Definition(c,id);ScopeCompany(c,scope);if(weight<0||period.EffectiveTo is not null&&period.EffectiveFrom>=period.EffectiveTo)Fail(DiagnosticCodes.PerformanceInvalidWeight);lock(sync){if(assignments.Any(x=>x.CompanyId==c&&x.KpiDefinitionVersionId==id&&x.Scope==scope&&x.Active&&x.EffectivePeriod.Overlaps(period)))Fail(DiagnosticCodes.PerformanceKpiAssignmentAmbiguous);var dto=new KpiAssignmentDto(KpiAssignmentId.From(Guid.NewGuid()),c,id,scope,weight,period,true,scoringFormulaVersionId);assignments.Add(dto);Audit(c,"PERFORMANCE.KPI_ASSIGNMENT_CHANGED","KpiAssignment",dto.Id.Value,cancellationToken).GetAwaiter().GetResult();return dto;}}
 public async ValueTask<KpiResultDto>SubmitResultAsync(CompanyId c,KpiScope scope,KpiDefinitionVersionId id,PerformancePeriod period,KpiMeasuredValue value,KpiResultSourceType source,string? sourceSystem,string? sourceReference,string? idempotencyKey,KpiResultId? supersedesResultId=null,CancellationToken cancellationToken=default)
 {Scope(c);ScopeCompany(c,scope);var definition=Definition(c,id);if(!period.IsValid)Fail(DiagnosticCodes.PerformanceInvalidResultRange);ValidateValue(definition,value);var fingerprint=Hash(string.Join('|',c.Value,id.Value,ScopeKey(scope),period.Code,period.DateFrom,period.DateTo,value.DataType,value.AsDecimal().ToString(CultureInfo.InvariantCulture),source,sourceSystem,sourceReference,supersedesResultId?.Value));lock(sync){if(!string.IsNullOrWhiteSpace(idempotencyKey)){var existing=facts.SingleOrDefault(x=>x.CompanyId==c&&x.IdempotencyKey==idempotencyKey);if(existing is not null){if(existing.Fingerprint!=fingerprint)Fail(DiagnosticCodes.PerformanceResultIdempotencyConflict);return existing;}}if(supersedesResultId is{ } old){var prior=facts.SingleOrDefault(x=>x.Id==old);if(prior is null||prior.CompanyId!=c||prior.Scope!=scope||prior.KpiDefinitionVersionId!=id)Fail(DiagnosticCodes.PerformanceCrossCompanyReference);if(facts.Any(x=>x.SupersedesResultId==old))Fail(DiagnosticCodes.PerformanceDuplicateResult);}var dto=new KpiResultDto(KpiResultId.From(Guid.NewGuid()),c,scope,id,period,value,source,Optional(sourceSystem),Optional(sourceReference),timeProvider.GetUtcNow(),currentUser.UserId,correlationContext.CorrelationId,Optional(idempotencyKey),supersedesResultId,fingerprint);facts.Add(dto);Audit(c,supersedesResultId is null?"PERFORMANCE.KPI_RESULT_SUBMITTED":"PERFORMANCE.KPI_RESULT_CORRECTED","KpiResult",dto.Id.Value,cancellationToken).GetAwaiter().GetResult();return dto;}}
 public async ValueTask<PerformancePolicyVersionDto>CreatePolicyDraftAsync(CompanyId c,string code,EffectivePeriod period,WeightNormalization normalization,IReadOnlyList<PerformanceGateDto> gates,IReadOnlyList<DerivedPayrollInputMapping> outputs,PerformancePolicyDefinitionId? definitionId=null,PayCalc24.Contracts.FormulaRepository.FormulaVersionId? overallFormulaVersionId=null,CancellationToken cancellationToken=default)
 {Scope(c);if(string.IsNullOrWhiteSpace(code)||outputs.Count==0)Fail(DiagnosticCodes.PerformancePolicyNotFound);if(gates.GroupBy(x=>x.Priority).Any(x=>x.Count()>1))Fail(DiagnosticCodes.PerformanceGateDuplicatePriority);if(gates.Any(x=>x.CompanyId!=c||string.IsNullOrWhiteSpace(x.Code)))Fail(DiagnosticCodes.PerformanceCrossCompanyReference);lock(sync){var def=definitionId??PerformancePolicyDefinitionId.From(Guid.NewGuid());var existing=policies.Where(x=>x.DefinitionId==def).ToArray();if(existing.Any(x=>x.CompanyId!=c))Fail(DiagnosticCodes.PerformanceCrossCompanyReference);var dto=new PerformancePolicyVersionDto(PerformancePolicyVersionId.From(Guid.NewGuid()),def,c,code.Trim(),existing.Length+1,period,KpiLifecycleStatus.DRAFT,normalization,overallFormulaVersionId,gates.OrderBy(x=>x.Priority).ThenBy(x=>x.Id.Value).ToArray(),outputs.ToArray());policies.Add(dto);return dto;}}
 public async ValueTask<PerformancePolicyVersionDto>PublishPolicyAsync(CompanyId c,PerformancePolicyVersionId id,CancellationToken cancellationToken=default){Scope(c);lock(sync){var p=Policy(c,id);if(p.LifecycleStatus!=KpiLifecycleStatus.DRAFT)Fail(DiagnosticCodes.PerformancePublishedPolicyImmutable);if(policies.Any(x=>x.Id!=id&&x.DefinitionId==p.DefinitionId&&x.LifecycleStatus==KpiLifecycleStatus.PUBLISHED&&x.EffectivePeriod.Overlaps(p.EffectivePeriod)))Fail(DiagnosticCodes.PerformancePolicyAmbiguous);var published=p with{LifecycleStatus=KpiLifecycleStatus.PUBLISHED};policies[policies.IndexOf(p)]=published;Audit(c,"PERFORMANCE.POLICY_PUBLISHED","PerformancePolicyVersion",id.Value,cancellationToken).GetAwaiter().GetResult();return published;}}
 public async ValueTask<PerformanceEvaluationResultDto>EvaluateAsync(PerformanceEvaluationRequest request,CancellationToken cancellationToken=default)
 {Scope(request.CompanyId);ScopeCompany(request.CompanyId,request.Scope);if(!request.Period.IsValid||string.IsNullOrWhiteSpace(request.EngineVersion))Fail(DiagnosticCodes.PerformanceBlockingValidationFailed);var policy=Policy(request.CompanyId,request.PolicyVersionId);if(policy.LifecycleStatus!=KpiLifecycleStatus.PUBLISHED&&request.ExecutionMode is PerformanceExecutionMode.PRODUCTION or PerformanceExecutionMode.REPLAY)Fail(DiagnosticCodes.PerformancePolicyNotFound);var selectedAssignments=request.AssignmentIds.Select(x=>Assignment(request.CompanyId,x)).ToArray();if(selectedAssignments.Length==0)Fail(DiagnosticCodes.PerformanceKpiAssignmentNotFound);if(selectedAssignments.Any(x=>x.Scope!=request.Scope||!x.EffectivePeriod.Contains(request.EvaluationBusinessDate)))Fail(DiagnosticCodes.PerformanceKpiAssignmentNotFound);var selectedFacts=request.ResultIds.Select(x=>Fact(request.CompanyId,x)).ToArray();var canonical=Inputs(request.PayrollInputs);var weights=Weights(selectedAssignments,policy.WeightNormalization);var details=new List<PerformanceKpiDetail>();foreach(var a in selectedAssignments.OrderBy(x=>x.Id.Value)){var matches=selectedFacts.Where(x=>x.Scope==request.Scope&&x.KpiDefinitionVersionId==a.KpiDefinitionVersionId&&x.Period==request.Period&&!selectedFacts.Any(y=>y.SupersedesResultId==x.Id)).ToArray();if(matches.Length==0)Fail(DiagnosticCodes.PerformanceRequiredInputMissing);if(matches.Length>1)Fail(DiagnosticCodes.PerformanceDuplicateResult);var fact=matches[0];var definition=Definition(request.CompanyId,a.KpiDefinitionVersionId);var achievement=expressions.Score(definition,a,fact,canonical);var weight=weights[a.Id];details.Add(new(a.Id,a.KpiDefinitionVersionId,fact.Id,fact.MeasuredValue.AsDecimal(),achievement,weight,achievement*weight));canonical[$"KPI.{definition.Content.Code}"]=achievement;}var overall=expressions.Aggregate(policy,details,canonical);canonical["OVERALL_ACHIEVEMENT"]=overall;var final=overall;var traces=new List<PerformanceGateTrace>();foreach(var g in policy.Gates.Where(x=>x.Enabled).OrderBy(x=>x.Priority).ThenBy(x=>x.Id.Value)){bool matched;try{matched=expressions.GateMatches(g,canonical);}catch(Exception ex){throw Error(DiagnosticCodes.PerformanceGateEvaluationFailed,new(){{"gate",g.Code},{"reason",ex.GetType().Name}});}var before=final;if(matched){final=g.EffectType switch{PerformanceGateEffectType.PASS=>final,PerformanceGateEffectType.FAIL=>0m,PerformanceGateEffectType.CAP when g.EffectValue is not null=>Math.Min(final,g.EffectValue.Value),PerformanceGateEffectType.MULTIPLY when g.EffectValue is not null=>final*g.EffectValue.Value,PerformanceGateEffectType.OVERRIDE or PerformanceGateEffectType.SET_VALUE when g.EffectValue is not null=>g.EffectValue.Value,PerformanceGateEffectType.OTHER=>expressions.GateResult(g,final,canonical),_=>throw Error(DiagnosticCodes.PerformanceGateInvalidEffect,new(){{"gate",g.Code}})};canonical["FINAL_ACHIEVEMENT"]=final;}traces.Add(new(g.Id,g.Code,g.Priority,matched,g.EffectType,before,final));if(matched&&g.StopOnMatch)break;}canonical["FINAL_ACHIEVEMENT"]=final;
 var formulaIds=selectedAssignments.Select(x=>x.ScoringFormulaVersionId).Append(policy.OverallFormulaVersionId).Concat(policy.Gates.SelectMany(x=>new[]{x.ConditionFormulaVersionId,x.ResultFormulaVersionId})).Where(x=>x.HasValue).Select(x=>x!.Value).Distinct().OrderBy(x=>x.Value).ToArray();var parameterIds=selectedAssignments.Where(x=>x.ParameterSetVersionId.HasValue).Select(x=>x.ParameterSetVersionId!.Value).Distinct().OrderBy(x=>x.Value).ToArray();var lookupIds=selectedAssignments.Where(x=>x.LookupTableVersionId.HasValue).Select(x=>x.LookupTableVersionId!.Value).Distinct().OrderBy(x=>x.Value).ToArray();var ruleIds=selectedAssignments.Where(x=>x.RuleSetVersionId.HasValue).Select(x=>x.RuleSetVersionId!.Value).Concat(policy.Gates.Where(x=>x.ConditionRuleSetVersionId.HasValue).Select(x=>x.ConditionRuleSetVersionId!.Value)).Distinct().OrderBy(x=>x.Value).ToArray();var sourceInputIds=request.PayrollInputs.Select(x=>x.LedgerEntryId).Distinct().OrderBy(x=>x.Value).ToArray();var hash=ResultHash(request,policy,details,traces,formulaIds.Select(x=>x.Value.ToString("D")),parameterIds.Select(x=>x.Value.ToString("D")),lookupIds.Select(x=>x.Value.ToString("D")),ruleIds.Select(x=>x.Value.ToString("D")),sourceInputIds.Select(x=>x.Value.ToString("D")),overall,final);var derived=new List<PayrollInputLedgerEntryDto>();if(request.ExecutionMode==PerformanceExecutionMode.PRODUCTION){if(request.PayrollPeriodId is null)Fail(DiagnosticCodes.PerformanceRequiredInputMissing);foreach(var output in policy.Outputs.OrderBy(x=>x.InputCode,StringComparer.Ordinal)){var number=canonical.TryGetValue(output.ResultField,out var v)?v:throw Error(DiagnosticCodes.PerformanceRequiredInputMissing,new(){{"input",output.ResultField}});var definition=inputDefinitions.ResolveEffective(request.CompanyId,output.InputCode,request.EvaluationBusinessDate);if(definition.Content.DataType!=output.DataType||definition.Content.UnitType!=output.UnitType)Fail(DiagnosticCodes.PerformanceInvalidResultType);var value=ToValue(nu