 var trace=new PerformanceExplainNode("PERFORMANCE_EVALUATION",policy.Code,final,[..details.OrderBy(x=>x.AssignmentId.Value).Select(x=>new PerformanceExplainNode("KPI",Definition(request.CompanyId,x.DefinitionVersionId).Content.Code,x.Achievement,[])),new("OVERALL_ACHIEVEMENT",null,overall,[]),..traces.Select(x=>new PerformanceExplainNode("GATE",x.Code,x.ValueAfter,[])),new("FINAL_ACHIEVEMENT",null,final,[])]);var result=new PerformanceEvaluationResultDto(PerformanceEvaluationResultId.From(Guid.NewGuid()),request.CompanyId,request.Scope,request.Period,policy.Id,overall,final,details,traces,formulaIds,parameterIds,lookupIds,ruleIds,sourceInputIds,trace,hash,request.EngineVersion,request.ExecutionMode,request.CorrelationId,derived);lock(sync)evaluations.Add(result);await Audit(request.CompanyId,"PERFORMANCE.EVALUATION_FINALIZED","PerformanceEvaluationResult",result.Id.Value,cancellationToken);return result;}
 private static Dictionary<KpiAssignmentId,decimal>Weights(IReadOnlyList<KpiAssignmentDto> a,WeightNormalization n){if(a.Any(x=>x.Weight<0))Fail(DiagnosticCodes.PerformanceInvalidWeight);var sum=a.Sum(x=>x.Weight);if(n==WeightNormalization.REQUIRE_SUM_ONE&&sum!=1m||n==WeightNormalization.NORMALIZE_TO_ONE&&sum==0m)Fail(DiagnosticCodes.PerformanceInvalidWeight);return a.ToDictionary(x=>x.Id,x=>n==WeightNormalization.NORMALIZE_TO_ONE?x.Weight/sum:x.Weight);}
 private static Dictionary<string,decimal>Inputs(IReadOnlyList<PerformanceInput> inputs){var result=new Dictionary<string,decimal>(StringComparer.Ordinal);foreach(var i in inputs.OrderBy(x=>x.Code,StringComparer.Ordinal)){if(result.ContainsKey(i.Code))Fail(DiagnosticCodes.PerformanceRequiredInputMissing);result[i.Code]=i.Value.DataType switch{PayrollInputDataType.DECIMAL=>i.Value.DecimalValue!.Value,PayrollInputDataType.INTEGER=>i.Value.IntegerValue!.Value,PayrollInputDataType.BOOLEAN=>i.Value.BooleanValue==true?1m:0m,_=>throw Error(DiagnosticCodes.PerformanceInvalidResultType,new(){{"input",i.Code}})};}return result;}
 private static PayrollInputValue ToValue(decimal v,PayrollInputDataType t)=>t switch{PayrollInputDataType.DECIMAL=>PayrollInputValue.Decimal(v),PayrollInputDataType.INTEGER when v==decimal.Truncate(v)=>PayrollInputValue.Integer(decimal.ToInt64(v)),PayrollInputDataType.BOOLEAN=>PayrollInputValue.Boolean(v!=0m),_=>throw Error(DiagnosticCodes.PerformanceInvalidResultType,[])};
 private static void ValidateValue(KpiDefinitionVersionDto d,KpiMeasuredValue v){if(d.Content.DataType!=v.DataType)Fail(DiagnosticCodes.PerformanceInvalidResultType);var n=v.AsDecimal();if(d.Content.MinValue is{ } min&&n<min||d.Content.MaxValue is{ } max&&n>max)Fail(DiagnosticCodes.PerformanceInvalidResultRange);}
 private KpiDefinitionVersionDto Definition(CompanyId c,KpiDefinitionVersionId id){var x=definitions.SingleOrDefault(x=>x.Id==id);if(x is null)Fail(DiagnosticCodes.PerformanceKpiDefinitionNotFound);if(x.CompanyId!=c)Fail(DiagnosticCodes.PerformanceCrossCompanyReference);return x;}
 private KpiAssignmentDto Assignment(CompanyId c,KpiAssignmentId id){var x=assignments.SingleOrDefault(x=>x.Id==id);if(x is null)Fail(DiagnosticCodes.PerformanceKpiAssignmentNotFound);if(x.CompanyId!=c)Fail(DiagnosticCodes.PerformanceCrossCompanyReference);return x;}
 private KpiResultDto Fact(CompanyId c,KpiResultId id){var x=facts.SingleOrDefault(x=>x.Id==id);if(x is null)Fail(DiagnosticCodes.PerformanceRequiredInputMissing);if(x.CompanyId!=c)Fail(DiagnosticCodes.PerformanceCrossCompanyReference);return x;}
 private PerformancePolicyVersionDto Policy(CompanyId c,PerformancePolicyVersionId id){var x=policies.SingleOrDefault(x=>x.Id==id);if(x is null)Fail(DiagnosticCodes.PerformancePolicyNotFound);if(x.CompanyId!=c)Fail(DiagnosticCodes.PerformanceCrossCompanyReference);return x;}
 private void Scope(CompanyId c){if(companyContext.CompanyId!=c)Fail(DiagnosticCodes.PerformanceCrossCompanyReference);}private void ScopeCompany(CompanyId c,KpiScope s){if(s.Type==KpiScopeType.INDIVIDUAL&&s.PayrollSubjectId is null||scopeResolver.FindCompany(s)!=c)Fail(DiagnosticCodes.PerformanceCrossCompanyReference);}
 private ValueTask Audit(CompanyId c,string action,string type,Guid id,CancellationToken ct)=>auditWriter.WriteAsync(new(c,currentUser.UserId,action,type,id.ToString("D"),correlationContext.CorrelationId,timeProvider.GetUtcNow(),new Dictionary<string,object?>()),ct);
 private static string ResultHash(PerformanceEvaluationRequest r,PerformancePolicyVersionDto p,IReadOnlyList<PerformanceKpiDetail>d,IReadOnlyList<PerformanceGateTrace>g,IEnumerable<string>f,IEnumerable<string>pa,IEnumerable<string>l,IEnumerable<string>rules,IEnumerable<string>inputs,decimal o,decimal final)=>Hash(string.Join('|',r.CompanyId.Value,ScopeKey(r.Scope),r.Period.Code,r.Period.DateFrom,r.Period.DateTo,p.Id.Value,string.Join(';',d.OrderBy(x=>x.AssignmentId.Value).Select(x=>$"{x.AssignmentId.Value:D},{x.DefinitionVersionId.Value:D},{x.ResultId.Value:D},{x.MeasuredValue.ToString(CultureInfo.InvariantCulture)},{x.Achievement.ToString(CultureInfo.InvariantCulture)},{x.Weight.ToString(CultureInfo.InvariantCulture)}")),string.Join(';',g.OrderBy(x=>x.Priority).ThenBy(x=>x.GateId.Value).Select(x=>$"{x.GateId.Value:D},{x.Priority},{x.Matched},{x.EffectType},{x.ValueAfter.ToString(CultureInfo.InvariantCulture)}")),string.Join(',',f),string.Join(',',pa),string.Join(',',l),string.Join(',',rules),string.Join(',',inputs),o.ToString(CultureInfo.InvariantCulture),final.ToString(CultureInfo.InvariantCulture),r.EngineVersion));
